/**
 * IMO and IPhO results for the ASEAN countries, 2000 → now.
 * Generated by `node scripts/fetch-olympiads.mjs` – re-run after each olympiad (July) to update.
 */
import countriesJson from './countries.json';
import imoJson from './imo.json';
import iphoJson from './ipho.json';

export type Award = 'G' | 'S' | 'B' | 'HM' | null;
export interface YearResult {
  year: number;
  rank?: number | null;
  points?: number | null;
  gold: number;
  silver: number;
  bronze: number;
  hm: number;
  contestants?: number;
}
export interface Contestant {
  year: number;
  name: string;
  rank: number | null;
  award: Award;
  points?: number | null;
  url?: string;
}
export interface Competition {
  competition: 'IMO' | 'IPhO';
  name: string;
  source: string;
  official: boolean;
  sourceNote?: string;
  fetched: string;
  years: Record<string, { countries: number; contestants?: number | null }>;
  countries: Record<string, { results: YearResult[]; contestants: Contestant[] }>;
}
export interface AseanCountry {
  key: string;
  en: string;
  km: string;
  imo: string;
  ipho: string | null;
}

export const ASEAN = countriesJson as AseanCountry[];
export const IMO = imoJson as unknown as Competition;
export const IPHO = iphoJson as unknown as Competition;
export const COMPETITIONS = [IMO, IPHO];

export const countryName = (key: string) => ASEAN.find((c) => c.key === key)!;

/** Totals per country, sorted like an Olympic medal table (gold, silver, bronze, HM). */
export function medalTable(c: Competition) {
  return ASEAN.filter((a) => c.countries[a.key])
    .map((a) => {
      const rs = c.countries[a.key].results;
      const sum = (k: 'gold' | 'silver' | 'bronze' | 'hm') => rs.reduce((n, r) => n + r[k], 0);
      const ranked = rs.filter((r) => r.rank);
      const best = ranked.length ? ranked.reduce((b, r) => (r.rank! < b.rank! ? r : b)) : null;
      return {
        key: a.key,
        country: a,
        participations: rs.length,
        first: rs[0]?.year,
        gold: sum('gold'),
        silver: sum('silver'),
        bronze: sum('bronze'),
        hm: sum('hm'),
        bestRank: best?.rank ?? null,
        bestRankYear: best?.year ?? null,
      };
    })
    .sort((a, b) => b.gold - a.gold || b.silver - a.silver || b.bronze - a.bronze || b.hm - a.hm || b.participations - a.participations);
}

export const yearsOf = (c: Competition) =>
  [...new Set(Object.values(c.countries).flatMap((x) => x.results.map((r) => r.year)))].sort((a, b) => b - a);

export const resultFor = (c: Competition, key: string, year: number) => c.countries[key]?.results.find((r) => r.year === year);

export const AWARD_LABEL: Record<string, string> = { G: 'Gold', S: 'Silver', B: 'Bronze', HM: 'Honourable Mention' };
